SEC_NAME = {'transport': 'תחבורה', 'water': 'מים', 'health': 'בריאות', 'env': 'איכות הסביבה', 'justice': 'משפט', 'welfare': 'רווחה', 'agri': 'חקלאות', 'bsheva': 'באר שבע'}
ORG = {'transport': 'משרד התחבורה והבטיחות בדרכים', 'water': 'הרשות הממשלתית למים ולביוב', 'health': 'משרד הבריאות', 'env': 'המשרד להגנת הסביבה', 'justice': 'משרד המשפטים', 'welfare': 'משרד הרווחה והביטחון החברתי', 'agri': 'משרד החקלאות וביטחון המזון', 'bsheva': 'עיריית באר שבע'}

def sector(scene):
    key, hook, names, picks, cta, qs = SEC[scene]; o = S['sector_top'][ORG[key]]; nm = SEC_NAME[key]
    L = qs is not None
    out = [(0, .4, hook), (1, .5, f"באתר {BRAND} יש {o['datasets']} מאגרי מידע של {nm}, ולמעלה מ-{mil(o['records'])} שורות נתונים.")]
    gap = 7 if L else 2.1; first = .6 if L else .9
    for i, (n, p) in enumerate(zip(names, picks)):
        r = o['top'][p]['records']
        out.append((2 + i, .6, f"{n}. כ-{mil(r)} שורות.") if L else (2, first + i * gap, f"{n}."))
    if L:
        out += [(5, .3, 'מה אפשר לגלות?'), (5, 1.3, qs[0]), (5, 3.3, qs[1]), (5, 5.3, qs[2]),
                (6, .5, f"{mil(o['records'])} שורות נתונים, שמחכות שמישהו יקרא אותן."), (7, .4, f"{cta} כל הנתונים, בעברית.")]
    else:
        out.append((3, .3, f"{cta} כל הנתונים, בעברית."))
    return out

